import {
  Column,
  CreateDateColumn,
  Entity,
  Index,
  PrimaryGeneratedColumn,
  UpdateDateColumn,
} from "typeorm";
import {
  TransactionPlatform,
  TransactionSourceType,
} from "../enums/transaction-sync.enum.js";

@Entity("transaction_sources")
@Index("IDX_TRANSACTION_SOURCE_USER_DEVICE", ["userId", "deviceId"], {
  unique: true,
})
export class TransactionSource {
  @PrimaryGeneratedColumn("uuid")
  id: string;

  // Owner of this registered device
  @Column({ type: "uuid" })
  userId: string;

  // UUID generated by the companion application
  @Column({ type: "varchar", length: 100 })
  deviceId: string;

  @Column({
    type: "varchar",
    length: 64,
    nullable: true,
    select: false,
  })
  deviceTokenHash: string | null;

  @Column({
    type: "varchar",
    length: 20,
  })
  platform: TransactionPlatform;

  @Column({
    type: "varchar",
    length: 30,
  })
  sourceType: TransactionSourceType;

  @Column({
    type: "varchar",
    length: 100,
    nullable: true,
  })
  deviceName: string | null;

  @Column({ type: "boolean", default: true })
  isActive: boolean;

  @Column({
    type: "timestamptz",
    nullable: true,
  })
  lastSyncAt: Date | null;

  @CreateDateColumn({ type: "timestamptz" })
  createdAt: Date;

  @UpdateDateColumn({ type: "timestamptz" })
  updatedAt: Date;
}
